with enriched as (select *, ntile(10) over w_recent as amount_bucket, round(amount / sum(amount) over (partition by customer_id), 4) as amount_share, avg(discount) over (partition by channel, customer_id order by amount, id rows between 3 preceding and current row) as discount_avg_3, corr(shipping_fee, discount) over w_hist as corr_shipping_fee_discount from orders window w_recent as (partition by status order by amount, id), w_hist as (partition by customer_id)) select id, order_date, channel, amount, discount, amount_bucket, corr_shipping_fee_discount, case when channel rlike '^(partner|store)$' then 'OTHER_ZONE' when channel rlike '^(web|mobile)$' then 'EXTENDED' else 'GROUP_B' end as channel_zone from enriched order by channel_zone;
